package br.com.admeclesial.interfaces.web.matrimonio; import br.com.admeclesial.application.matrimonio.*; import br.com.admeclesial.application.organizacao.OrganizacaoEclesialApplicationService; import br.com.admeclesial.application.pessoa.PessoaApplicationService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.util.*; @Controller public class CelebracaoMatrimonialWebController { final CelebracaoMatrimonialApplicationService s; final ProcessoMatrimonialApplicationService p; final OrganizacaoEclesialApplicationService org; final PessoaApplicationService pessoa; public CelebracaoMatrimonialWebController(CelebracaoMatrimonialApplicationService s,ProcessoMatrimonialApplicationService p,OrganizacaoEclesialApplicationService o,PessoaApplicationService pe){this.s=s;this.p=p;org=o;pessoa=pe;} @GetMapping("/processos-matrimoniais/{uuid}/celebracao") public String form(@PathVariable UUID uuid,Model m){m.addAttribute("processo",p.buscar(uuid));m.addAttribute("organizacoes",org.listar());m.addAttribute("pessoas",pessoa.listar());return "matrimonio/celebracao-form";} @PostMapping("/processos-matrimoniais/{uuid}/celebracao") public String salvar(@PathVariable UUID uuid,@RequestParam UUID organizacaoEclesialUuid,@RequestParam UUID celebranteUuid,@RequestParam java.time.LocalDate dataCelebracao,@RequestParam(required=false) String local,@RequestParam(required=false) String observacao){s.salvar(new CelebracaoMatrimonialRequest(uuid,organizacaoEclesialUuid,celebranteUuid,dataCelebracao,local,observacao));return "redirect:/processos-matrimoniais/"+uuid;} }